"""Data models used by the simulator."""

from dataclasses import dataclass, field
from math import hypot
from typing import Dict, List, Tuple


@dataclass
class Position:
    """Two-dimensional coordinate inside the simulated road area."""

    x: float
    y: float

    def distance_to(self, other: "Position") -> float:
        """Euclidean distance used by mobility, range checks, and packet loss."""

        return hypot(self.x - other.x, self.y - other.y)


@dataclass
class Task:
    """One computational job generated by a vehicle.

    A task has an input data size for transmission, a CPU demand for processing,
    and a deadline. The offloader decides where this task should be processed.
    """

    task_id: int
    vehicle_id: int
    created_at_step: int
    data_size_mbits: float
    compute_cycles_g: float
    deadline_s: float


@dataclass
class Vehicle:
    """A normal vehicle that can create tasks and process its own tasks locally."""

    node_id: int
    position: Position
    compute_gps: float
    speed_mps: float
    direction_rad: float
    queue_s: float = 0.0


@dataclass
class ProviderVehicle:
    """A mobile provider vehicle acting as an edge processor or relay."""

    node_id: int
    position: Position
    compute_gps: float
    queue_s: float = 0.0


@dataclass
class EdgeServer:
    """A fixed edge server with higher compute capacity than vehicles."""

    node_id: int
    position: Position
    compute_gps: float
    queue_s: float = 0.0


@dataclass(frozen=True)
class Link:
    """One wireless hop between two nodes.

    `loss_probability` is the estimated packet-loss probability for the hop.
    `tx_delay_s` already includes the expected effect of retransmissions.
    """

    source_id: str
    target_id: str
    loss_probability: float
    tx_delay_s: float
    expected_retransmissions: float


@dataclass(frozen=True)
class OffloadCandidate:
    """One valid action considered by the task-offloading baseline.

    Examples are local processing, vehicle-to-provider, vehicle-to-edge, and
    vehicle-provider-edge. Invalid actions never become candidates.
    """

    destination_type: str
    destination_id: int
    route_name: str
    route: Tuple[str, ...]
    links: Tuple[Link, ...]
    processing_delay_s: float
    total_delay_s: float
    packet_loss_probability: float
    expected_retransmissions: float
    missed_deadline: bool
    score: float


@dataclass
class OffloadDecision:
    """The selected candidate for one task plus whether the task was in a blind spot."""

    task: Task
    candidate: OffloadCandidate
    blind_spot: bool


@dataclass
class StepMetrics:
    """Aggregated results for one simulation time step.

    The provider location fields are optional in spirit but always filled by the
    runners. They support the required provider-location plots in Phase 2.
    """

    step: int
    task_count: int = 0
    average_delay_s: float = 0.0
    average_packet_loss: float = 0.0
    expected_retransmissions: float = 0.0
    missed_deadlines: int = 0
    blind_spots: int = 0
    average_provider_x: float = 0.0
    average_provider_y: float = 0.0
    destination_counts: Dict[str, int] = field(default_factory=dict)
    route_counts: Dict[str, int] = field(default_factory=dict)


@dataclass
class SimulationSummary:
    """Aggregated results for a full scenario run.

    `method_name` is `baseline` for Phase 1-style runs and `sdn_ppo_kalman` for
    the full Phase 2 method. Keeping it inside the summary makes comparison CSVs
    and plots straightforward.
    """

    scenario_name: str
    method_name: str
    vehicle_count: int
    provider_count: int
    edge_count: int
    steps: int
    task_count: int
    average_delay_s: float
    average_packet_loss: float
    expected_retransmissions: float
    missed_deadlines: int
    blind_spots: int
    average_provider_x: float
    average_provider_y: float
    destination_counts: Dict[str, int]
    route_counts: Dict[str, int]
    step_metrics: List[StepMetrics]
